  const isRiskOperation=(current:TradeRecord)=>{const prior=JSON.parse(baseline.current) as TradeRecord;return hasExecution(current)&&!hasExecution(prior)||current.recordType==='plan'||!!current.entries?.some(entry=>!prior.entries?.some(old=>old.id===entry.id))||current.originalStop!==prior.originalStop||current.currentStop!==prior.currentStop;};
  const close=()=>{if(busy)return;if(dirty()&&!window.confirm('这笔交易的修改尚未保存，确定关闭吗？'))return;onClose();};
  const dialog=useDialogFocus(close);
