  useEffect(()=>{const warn=(e:BeforeUnloadEvent)=>{if(dirty()){e.preventDefault();e.returnValue='';}};window.addEventListener('beforeunload',warn);return()=>window.removeEventListener('beforeunload',warn);},[]);
  const change=(patch:Partial<TradeRecord>,render=true)=>{ref.current={...ref.current,...patch};if(patch.contract){const contract=tradeContract(ref.current,settings);ref.current={...ref.current,entries:ref.current.entries?.map(e=>e.feeSource==='estimated'?{...e,fees:estimatedExecutionFee(contract,e.quantity,e.price,'entry')}:e),closes:ref.current.closes.map(e=>e.feeSource==='estimated'?{...e,fees:estimatedExecutionFee(contract,e.quantity,e.price,'exit')}:e)};}if(patch.quantity!==undefined||patch.closes!==undefined||patch.entries!==undefined||patch.events!==undefined)ref.current=syncStatus(ref.current);const calculate=Object.keys(patch).some(k=>['entryPrice','quantity','originalStop','currentStop','targetPrice','entries','closes','direction','framework','contract','g1','aggregateEntryFee','instrument'].includes(k));if(calculate)ref.current=refreshAutomaticCloses(ref.current,settings);const p=vnextRiskAssessment(ref.current,settings);if(calculate&&ref.current.revision===0&&!ref.current.legacy){if(p.totalRisk!==null)ref.current={...ref.current,initialRisk:p.totalRisk,plannedRiskAtEntry:p.totalRisk,plannedRR:p.netRR};if(p.overHard)ref.current={...ref.current,riskCompliant:false};}if(render)setTrade(ref.current);};
