    const contract=template?current.contract??current.g1?.contract??structuredClone(config.contract):structuredClone(config.contract);
    const identity:Partial<TradeRecord>={instrument,symbol:template?current.symbol??config.symbol:config.symbol,accountId:template?current.accountId??config.accountId:config.accountId,quoteSource:template?current.quoteSource??config.quoteSource:config.quoteSource,contract,...(current.g1?{g1:{...current.g1,contract}}:{})};
